(function() {
  function otimizarImagensBlogger() {
    const widthWindow = window.innerWidth;
    let tamanhoAlvo = 'w1200-h675-c'; // Desktop 16:9

    if (widthWindow < 576) {
      tamanhoAlvo = 'w480-h360-c';   // Mobile 4:3
    } else if (widthWindow < 992) {
      tamanhoAlvo = 'w800-h450-c';   // Tablet 16:9
    }

    const imagens = document.querySelectorAll('img.responsive-lazy-blogger');

    imagens.forEach(img => {
      const urlOriginal = img.getAttribute('data-src');
      if (urlOriginal && !urlOriginal.startsWith('data:')) {
        let urlModificada = urlOriginal;

        if (urlOriginal.includes('/s1600/')) {
          urlModificada = urlOriginal.replace('/s1600/', '/' + tamanhoAlvo + '/');
        } else if (urlOriginal.includes('=s0') || urlOriginal.includes('=')) {
          urlModificada = urlOriginal.split('=')[0] + '=' + tamanhoAlvo;
        }

        img.src = urlModificada;
        img.classList.add('img-loaded');
      }
    });
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', otimizarImagensBlogger);
  } else {
    otimizarImagensBlogger();
  }
})();
